 {requirementBox&&<div className="modalBackdrop" onMouseDown={()=>!busy&&setRequirementBox(null)}><form className="requirementModal" onMouseDown={e=>e.stopPropagation()} onSubmit={async e=>{e.preventDefault();if(!requirementTitle.trim()||!requirementDescription.trim())return;setBusy(true);setRequirementError("");setError("");try{await api("/admin/couriers/"+requirementBox.courierId+"/requirements",token,"POST",{title:requirementTitle.trim(),description:requirementDescription.trim()});await load(token);setRequirementBox(null);setRequirementTitle("");setRequirementDescription("");setActivityNotice("Pendência enviada ao motoboy com sucesso");setTimeout(()=>setActivityNotice(""),7000)}catch(err:any){setRequirementError(err.message||"Não foi possível enviar a pendência");setError(err.message||"Não foi possível enviar a pendência")}finally{setBusy(false)}}}><div className="requirementModalHead"><div className="requirementModalIcon"><CircleAlert size={24}/></div><div><small>PENDÊNCIA DE CADASTRO</small><h2>Solicitar informação</h2><p>Envie uma solicitação clara para <b>{requirementBox.name}</b>. Ela ficará disponível na consulta de candidatura do motoboy.</p></div></div><div className="requirementGuide"><span>1</span><div><b>Seja específico</b><small>Informe exatamente qual documento ou dado precisa ser corrigido.</small></div></div><label>Título da pendência<input autoFocus value={requirementTitle} onChange={e=>setRequirementTitle(e.target.value)} placeholder="Ex.: Foto da CNH ilegível" required maxLength={100}/></label><label>Orientação para o motoboy<textarea value={requirementDescription} onChange={e=>setRequirementDescription(e.target.value)} placeholder="Ex.: Envie uma nova foto da CNH, frente e verso, com todos os dados legíveis." required maxLength={1000}/></label>{requirementError&&<div className="requirementError" role="alert">{displayMessage(requirementError)}</div>}<div className="modalActions"><button type="button" className="cancelBtn" disabled={busy} onClick={()=>setRequirementBox(null)}>Cancelar</button><button disabled={busy||!requirementTitle.trim()||!requirementDescription.trim()}>{busy?"Enviando...":"Enviar pendência ao motoboy"}</button></div></form></div>}
