function Card({label,value,note,icon:Icon}:{label:string,value:any,note:string,icon:LucideIcon}){return <article><div className="metricIcon"><Icon size={18} strokeWidth={2}/></div><span>{label}</span><strong>{value}</strong><small>{note}</small></article>}
function Dashboard({dash,orders,pending,withdrawals}:{dash:Row,orders:Row[],pending:Row[],withdrawals:Row[]}){
 const awaiting=orders.filter(o=>["PENDING","CONFIRMED"].includes(o.status)).length;
 const released=orders.filter(o=>["PREPARING","READY_FOR_PICKUP"].includes(o.status)).length;
 const searching=orders.filter(o=>o.status==="SEARCHING_COURIER").length;
 const active=orders.filter(o=>["COURIER_ASSIGNED","PICKED_UP","OUT_FOR_DELIVERY"].includes(o.status)).length;
 const finished=orders.filter(o=>o.status==="DELIVERED").length;
 const pendingWithdrawals=withdrawals.filter(w=>["PENDING","PROCESSING"].includes(w.status)).length;
 return <><section className="hero"><div><small>OPERAÇÃO EM TEMPO REAL</small><h2>Porto Prime,<br/>em uma visão.</h2><p>Acompanhe pedidos, equipe, pagamentos e catálogo com clareza operacional.</p><div className="heroSignal"><Activity size={15}/><span>Dados sincronizados com a operação</span></div></div><div className="pulse"><b>{active+searching}</b><span>operações ativas</span></div></section>
 <section className="metrics opsMetrics">
  <Card icon={ClipboardList} label="Aguardando" value={awaiting} note="Pedidos em análise"/>
  <Card icon={PackageSearch} label="Liberados" value={released} note="Preparação / retirada"/>
  <Card icon={Search} label="Procurando motoboy" value={searching} note="Despacho automático"/>
  <Card icon={Bike} label="Entregas ativas" value={active} note="Motoboy em operação"/>
  <Card icon={Check} label="Finalizados" value={finished} note="Pedidos entregues"/>
  <Card icon={Activity} label="Motoboys online" value={dash.onlineCouriers||0} note="Disponíveis agora"/>
  <Card icon={UserCheck} label="Cadastros pendentes" value={pending.length} note="Precisam de análise"/>
  <Card icon={Wallet} label="Saques pendentes" value={pendingWithdrawals} note="Pendente / processamento"/>
 </section>
 <section className="metrics financeMetrics">
  <Card icon={Banknote} label="Receita paga" value={brl(dash.revenue)} note="Pedidos confirmados"/>
  <Card icon={ClipboardList} label="Pedidos registrados" value={dash.orders||0} note="Histórico total"/>
 </section>
 <section className="grid"><Panel title="Pedidos recentes"><MiniOrders rows={orders.slice(0,6)}/></Panel><Panel title="Radar operacional"><div className="radar"><div className="radarIcon"><CircleDollarSign size={18}/></div><b>{dash.users||0}</b><span>usuários cadastrados</span><div className="radarIcon"><PackageSearch size={18}/></div><b>{dash.products||0}</b><span>produtos ativos</span></div></Panel></section></>
}
function Panel({title,children}:{title:string,children:React.ReactNode}){return <section className="panel"><div className="panelHead"><h3>{title}</h3><span>Dados em tempo real</span></div>{children}</section>}
function Badge({v}:{v:string}){return <span className={"badge b-"+v.toLowerCase()}>{statusLabel[v]||v}</span>}
function MiniOrders({rows}:{rows:Row[]}){return <div className="rows">{rows.map(o=><div className="row" key={o.id}><div className="order">#{o.id.slice(-6).toUpperCase()}</div><div className="grow"><b>{o.customer?.name}</b><span>{brl(o.total)}</span><small>{dt(o.createdAt)}</small></div><Badge v={o.status}/></div>)}</div>}
function Pending({rows,act,courierByUser,requestRequirement}:{rows:Row[],act:any,courierByUser:Record<string,Row>,requestRequirement:(app:Row,name:string)=>void}){
 const [detail,setDetail]=useState<Row|null>(null);
 const label=(key:string)=>({birthDate:"Data de nascimento",cpf:"CPF",document:"Documento",cnh:"CNH",cnhCategory:"Categoria CNH",cnhExpiry:"Validade da CNH",vehicleType:"Tipo do veículo",vehicleBrand:"Marca",vehicleModel:"Modelo",vehicleYear:"Ano",vehiclePlate:"Placa",pixKey:"Chave PIX",pixKeyType:"Tipo de chave PIX",cep:"CEP",postalCode:"CEP",street:"Rua",number:"Número",complement:"Complemento",neighborhood:"Bairro",city:"Cidade",state:"Estado",phone:"Telefone",email:"E-mail",businessName:"Estabelecimento"} as Record<string,string>)[key]||key.replace(/([A-Z])/g," $1").replace(/^./,s=>s.toUpperCase());
 const value=(v:any)=>v===null||v===undefined||v===""?"—":typeof v==="object"?JSON.stringify(v):String(v);
 if(!rows.length)return <section className="approvalEmpty"><div className="approvalEmptyIcon"><Check size={26}/></div><div><small>FILA DE ANÁLISE</small><h2>Tudo em dia por aqui.</h2><p>Nenhum cadastro está aguardando aprovação neste momento.</p></div></section>;
 return <><section className="approvalHero"><div><small>CENTRAL DE APROVAÇÕES</small><h2>Analise cada candidatura<br/>com segurança.</h2><p>Documentos, veículo e pendências reunidos em uma visão operacional limpa para decisões mais rápidas.</p></div><div className="approvalCount"><b>{rows.length}</b><span>{rows.length===1?"cadastro aguardando":"cadastros aguardando"}</span></div></section><div className="approvalGrid">{rows.map(x=>{const app=courierByUser[x.id]||x.courierProfile;const requirements:Row[]=app?.requirements||[];const unresolved=requirements.filter(r=>r.status!=="RESOLVED");const onboarding=x.courierProfile?.onboardingData||x.partnerProfile?.onboardingData||{};return <article className="approvalCard" key={x.id}><div className="approvalCardTop"><div className="approvalIdentity"><div className="approvalAvatar">{(x.name||"?").slice(0,1).toUpperCase()}</div><div><div className="approvalRole">{x.role==="COURIER"?"MOTOBOY":"PARCEIRO"}</div><h3>{x.name}</h3><span>Cadastrado em {dt(x.createdAt)}</span></div></div><Badge v={app?.approvalStatus||x.status}/></div><div className="approvalFacts"><div><span>Contato</span><b>{x.phone||"Não informado"}</b><small>{x.email}</small></div>{x.role==="COURIER"?<><div><span>Documento</span><b>{app?.document||onboarding.cpf||"—"}</b><small>CPF do candidato</small></div><div><span>Habilitação</span><b>{app?.cnh||onboarding.cnh||"—"}</b><small>{app?.cnhCategory?"Categoria "+app.cnhCategory:"CNH informada"}</small></div><div><span>Veículo</span><b>{[app?.vehicleBrand||onboarding.vehicleBrand,app?.vehicleModel||onboarding.vehicleModel].filter(Boolean).join(" ")||"—"}</b><small>{[app?.vehiclePlate||onboarding.vehiclePlate,app?.vehicleYear||onboarding.vehicleYear].filter(Boolean).join(" · ")||"Dados do veículo"}</small></div></>:<div><span>Estabelecimento</span><b>{x.partnerProfile?.businessName||onboarding.businessName||"—"}</b><small>{x.partnerProfile?.document||onboarding.document||"Cadastro parceiro"}</small></div>}</div>{x.role==="COURIER"&&app&&<section className={"approvalRequirements "+(unresolved.length?"hasPending":"")}><div className="approvalRequirementsHead"><div><span className="approvalDot"></span><div><b>{unresolved.length?unresolved.length+" pendência(s) em andamento":"Documentação sem pendências"}</b><small>{unresolved.length?"A aprovação fica bloqueada até a conclusão.":"Você pode solicitar informação adicional antes de aprovar."}</small></div></div><button className="secondary requirementTrigger" onClick={()=>requestRequirement(app,x.name)}>+ Solicitar pendência</button></div>{requirements.length>0&&<div className="approvalRequirementList">{requirements.slice(0,3).map(r=><div className="approvalRequirement" key={r.id}><div><b>{r.title}</b><Badge v={r.status}/></div><p>{r.description}</p>{r.response&&<div className="approvalResponse"><small>RESPOSTA RECEBIDA</small><span>{r.response}</span></div>}{r.status==="ANSWERED"&&<button onClick={()=>act("/admin/requirements/"+r.id+"/resolve","PATCH")}><Check size={14}/> Marcar como resolvida</button>}</div>)}</div>}</section>}<div className="approvalFooter"><button className="profileButton" onClick={()=>setDetail({user:x,app,onboarding})}>Ver dados completos</button><div className="approvalActions"><button className="danger" onClick={()=>act("/admin/users/"+x.id+"/reject")}>Rejeitar</button><button disabled={x.role==="COURIER"&&unresolved.length>0} title={unresolved.length?"Resolva todas as pendências antes de aprovar":""} onClick={()=>act("/admin/users/"+x.id+"/approve")}>{unresolved.length?"Aguardando pendências":"Aprovar cadastro"}</button></div></div></article>})}</div>{detail&&<div className="modalBackdrop profileBackdrop" onMouseDown={()=>setDetail(null)}><section className="profileModal" onMouseDown={e=>e.stopPropagation()}><div className="profileModalHero"><button className="profileClose" aria-label="Fechar" onClick={()=>setDetail(null)}><X size={18}/></button><div className="profileModalAvatar">{(detail.user.name||"?").slice(0,1).toUpperCase()}</div><div><small>DOSSIÊ DE CADASTRO</small><h2>{detail.user.name}</h2><p>{detail.user.role==="COURIER"?"Candidatura para motoboy":"Cadastro de parceiro"} · {detail.user.email}</p></div><Badge v={detail.app?.approvalStatus||detail.user.status}/></div><div className="profileSummary"><div><span>Telefone</span><b>{detail.user.phone||"—"}</b></div><div><span>Cadastrado em</span><b>{dt(detail.user.createdAt)}</b></div><div><span>ID do usuário</span><b>{detail.user.id}</b></div></div>{detail.user.role==="COURIER"&&<section className="profileSection"><div className="profileSectionTitle"><span>01</span><div><b>Documentos e veículo</b><small>Dados essenciais para análise operacional</small></div></div><div className="profileDataGrid"><div><span>CPF</span><b>{detail.app?.document||detail.onboarding?.cpf||"—"}</b></div><div><span>CNH</span><b>{detail.app?.cnh||detail.onboarding?.cnh||"—"}</b></div><div><span>Categoria</span><b>{detail.app?.cnhCategory||detail.onboarding?.cnhCategory||"—"}</b></div><div><span>Veículo</span><b>{[detail.app?.vehicleBrand||detail.onboarding?.vehicleBrand,detail.app?.vehicleModel||detail.onboarding?.vehicleModel].filter(Boolean).join(" ")||"—"}</b></div><div><span>Placa</span><b>{detail.app?.vehiclePlate||detail.onboarding?.vehiclePlate||"—"}</b></div><div><span>Ano</span><b>{detail.app?.vehicleYear||detail.onboarding?.vehicleYear||"—"}</b></div></div></section>}<section className="profileSection"><div className="profileSectionTitle"><span>02</span><div><b>Informações completas</b><small>Todos os campos enviados no formulário de cadastro</small></div></div><div className="profileDataGrid full">{Object.entries(detail.onboarding||{}).filter(([k,v])=>k!=="profilePhoto"&&v!==null&&v!==undefined&&v!=="").map(([k,v])=><div key={k}><span>{label(k)}</span><b>{value(v)}</b></div>)}{Object.keys(detail.onboarding||{}).length===0&&<div className="profileNoData"><b>Nenhum dado adicional armazenado.</b><span>Os dados principais acima continuam disponíveis para análise.</span></div>}</div></section>{detail.app?.requirements?.length>0&&<section className="profileSection"><div className="profileSectionTitle"><span>03</span><div><b>Histórico de pendências</b><small>Solicitações e respostas desta candidatura</small></div></div><div className="profileHistory">{detail.app.requirements.map((r:Row)=><div key={r.id}><div><b>{r.title}</b><Badge v={r.status}/></div><p>{r.description}</p>{r.response&&<strong>Resposta: {r.response}</strong>}</div>)}</div></section>}<div className="profileModalFooter"><span>PORTO PRIME · ANÁLISE ADMINISTRATIVA</span><button onClick={()=>setDetail(null)}>Concluir análise</button></div></section></div>}</>;
}

function People({rows,kind,act,ask,courierByUser,requestRequirement}:{rows:Row[],kind:string,act:any,ask:any,courierByUser:Record<string,Row>,requestRequirement:(app:Row,name:string)=>void}){
 const [selected,setSelected]=useState<Set<string>>(new Set());
 const [profileId,setProfileId]=useState<string|null>(null);
 const [courierQuery,setCourierQuery]=useState("");
 const detail=rows.find(x=>x.id===profileId);
 const detailApp=detail?(courierByUser[detail.id]||detail.courierProfile||{}):{};
 useEffect(()=>{if(!profileId)return;const close=(e:KeyboardEvent)=>{if(e.key==="Escape")setProfileId(null)};document.addEventListener("keydown",close);return()=>document.removeEventListener("keydown",close)},[profileId]);
 const visibleRows=kind==="Motoboy"?rows.filter(x=>[x.name,x.email,x.phone,courierByUser[x.id]?.document,x.courierProfile?.document].some(v=>String(v||"").toLowerCase().includes(courierQuery.trim().toLowerCase()))):rows;
 const bulkEnabled=kind==="Motoboy"||kind==="Cliente";
 useEffect(()=>{const valid=new Set(rows.map(x=>x.id));setSelected(prev=>new Set([...prev].filter(id=>valid.has(id))))},[rows]);
 const allVisible=bulkEnabled&&visibleRows.length>0&&visibleRows.every(x=>selected.has(x.id));
 const toggle=(id:string)=>setSelected(prev=>{const next=new Set(prev);next.has(id)?next.delete(id):next.add(id);return next});
 const toggleAll=()=>setSelected(prev=>{const next=new Set(prev);visibleRows.forEach(x=>allVisible?next.delete(x.id):next.add(x.id));return next});
 const selectedRows=rows.filter(x=>selected.has(x.id));
 const bulkDelete=()=>ask({
  title:"Excluir "+selectedRows.length+" "+(kind==="Motoboy"?"motoboy(s)":"cliente(s)")+"?",
  message:"Os cadastros selecionados serão removidos permanentemente da Porto Prime.",
  detail:kind==="Motoboy"?"Motoboys com entrega ativa serão preservados automaticamente. Os demais terão acesso e dados operacionais removidos.":"Clientes com histórico de pedidos serão preservados automaticamente para proteger o histórico operacional e financeiro.",
  confirm:"Excluir "+selectedRows.length+" selecionado(s)",
  action:async()=>{const result=await act("/admin/users/bulk-delete","POST",{ids:selectedRows.map(x=>x.id)});if(result)setSelected(new Set())}
 });
 return <><Panel title={kind+"s cadastrados"}>
 {kind==="Motoboy"&&<div className="orderSearchToolbar"><label className="orderNumberSearch"><Search size={18}/><input aria-label="Buscar motoboy por nome, CPF ou contato" placeholder="Buscar por nome, CPF ou contato…" value={courierQuery} onChange={e=>setCourierQuery(e.target.value)}/>{courierQuery&&<button aria-label="Limpar busca" onClick={()=>setCourierQuery("")}><X size={16}/></button>}</label><span>{visibleRows.length} motoboys encontrados</span></div>}
  {bulkEnabled&&<div className={"bulkBar "+(selected.size?"active":"")}>
   <div className="bulkSelectAll">
    <label className="checkControl"><input type="checkbox" checked={allVisible} onChange={toggleAll}/><span/></label>
    <div><b>{selected.size?selected.size+" selecionado(s)":"Seleção em massa"}</b><small>{selected.size?"Pronto para executar uma ação em lote":"Marque registros individualmente ou selecione todos os resultados visíveis"}</small></div>
   </div>
   <div className="bulkActions">
    {selected.size>0&&<button className="secondary" onClick={()=>setSelected(new Set())}>Limpar seleção</button>}
    <button className="bulkDeleteBtn" disabled={!selected.size} onClick={bulkDelete}>Excluir selecionados</button>
   </div>
  </div>}
  {kind==="Motoboy"?<div className="courierAdminGrid">{!visibleRows.length?<Empty text="Nenhum motoboy encontrado."/>:visibleRows.map(x=>{const app=courierByUser[x.id]||x.courierProfile;const unresolved=(app?.requirements||[]).filter((r:Row)=>r.status!=="RESOLVED");const isSelected=selected.has(x.id);return <article key={x.id} className={"courierAdminCard "+(isSelected?"selectedCourier":"")}><div className="courierAdminIdentity"><label className="checkControl"><input type="checkbox" aria-label={"Selecionar "+x.name} checked={isSelected} onChange={()=>toggle(x.id)}/></label><div className="courierAdminAvatar">{app?.onboardingData?.profilePhoto?<img src={app.onboardingData.profilePhoto} alt={"Foto de "+x.name}/>:((x.name||"?").slice(0,1).toUpperCase())}</div><div className="courierAdminName"><h3>{x.name}</h3><span>{app?.document||"CPF não informado"}</span></div><span className={"courierConnection "+(app?.isOnline?"online":"")}>{app?.isOnline?"Online":"Offline"}</span></div><div className="courierAdminFacts"><div><span>Contato</span><b>{x.phone||"Não informado"}</b><small>{x.email}</small></div><div><span>Veículo</span><b>{[app?.vehicleBrand,app?.vehicleModel].filter(Boolean).join(" ")||"Não informado"}</b><small>{app?.vehiclePlate||"Placa não informada"}</small></div></div><div className="courierAdminStatuses"><Badge v={app?.approvalStatus||x.status}/><Badge v={x.status}/>{unresolved.length>0&&<span className="courierPending">{unresolved.length} pendência(s)</span>}</div><div className="courierAdminPrimary"><button onClick={()=>setProfileId(x.id)}><Users size={16}/> Abrir perfil completo</button>{app&&<button className="secondary" onClick={()=>requestRequirement(app,x.name)}><ClipboardList size={16}/> Solicitar pendência</button>}</div><details className="courierAccess"><summary>Gerenciar acesso<ChevronDown size={16}/></summary><div className="actions">{x.status!=="ACTIVE"&&<button onClick={()=>act("/admin/users/"+x.id+"/status","PATCH",{status:"ACTIVE"})}><Check size={15}/> Ativar acesso</button>}{x.status==="ACTIVE"&&<button className="warn" onClick={()=>act("/admin/users/"+x.id+"/status","PATCH",{status:"SUSPENDED"})}><CircleAlert size={15}/> Suspender acesso</button>}{x.status!=="BLOCKED"&&<button className="danger" onClick={()=>act("/admin/users/"+x.id+"/status","PATCH",{status:"BLOCKED"})}><CircleAlert size={15}/> Bloquear acesso</button>}{bulkEnabled&&<button className="danger ghostDanger" onClick={()=>ask({title:"Excluir "+kind.toLowerCase()+" permanentemente?",message:"Você está prestes a remover "+x.name+" da Porto Prime.",detail:kind==="Motoboy"?"O cadastro, acesso e dados vinculados serão removidos. Motoboys com entrega ativa não podem ser excluídos.":"Clientes com histórico de pedidos são preservados para manter a integridade operacional e financeira.",confirm:"Sim, excluir "+kind.toLowerCase(),action:()=>act("/admin/users/"+x.id,"DELETE")})}><Trash2 size={15}/> Excluir cadastro</button>}</div></details></article>})}</div>:(!rows.length?<Empty text={"Nenhum "+kind.toLowerCase()+" encontrado."}/>:<div className="tableWrap bulkTable"><table><thead><tr>{bulkEnabled&&<th className="selectCol"><label className="checkControl"><input aria-label="Selecionar todos" type="checkbox" checked={allVisible} onChange={toggleAll}/><span/></label></th>}<th>Usuário</th><th>Contato</th><th>Status</th><th>{kind==="Motoboy"?"Operação":"Atividade"}</th><th>Ações</th></tr></thead><tbody>{rows.map(x=>{const app=kind==="Motoboy"?courierByUser[x.id]:null;const unresolved=(app?.requirements||[]).filter((r:Row)=>r.status!=="RESOLVED");const isSelected=selected.has(x.id);return <tr key={x.id} className={isSelected?"selectedRow":""}>{bulkEnabled&&<td className="selectCol"><label className="checkControl"><input aria-label={"Selecionar "+x.name} type="checkbox" checked={isSelected} onChange={()=>toggle(x.id)}/><span/></label></td>}<td><b>{x.name}</b><small>{dt(x.createdAt)}</small>{app&&<small>CPF {app.document||"—"} · {app.vehicleModel||"Moto não informada"}</small>}</td><td>{x.email}<small>{x.phone||"—"}</small></td><td><Badge v={app?.approvalStatus||x.status}/>{unresolved.length>0&&<small>{unresolved.length} pendência(s)</small>}</td><td>{kind==="Motoboy"?(x.courierProfile?.isOnline?"Online":"Offline"):(kind==="Cliente"?((x._count?.orders||0)+" pedidos"):(x.partnerProfile?.businessName||"—"))}</td><td><div className="actions">{kind==="Motoboy"&&app&&<button className="secondary" onClick={()=>requestRequirement(app,x.name)}>Solicitar pendência</button>}{x.status!=="ACTIVE"&&<button onClick={()=>act("/admin/users/"+x.id+"/status","PATCH",{status:"ACTIVE"})}>Ativar</button>}{x.status==="ACTIVE"&&<button className="warn" onClick={()=>act("/admin/users/"+x.id+"/status","PATCH",{status:"SUSPENDED"})}>Suspender</button>}{x.status!=="BLOCKED"&&<button className="danger" onClick={()=>act("/admin/users/"+x.id+"/status","PATCH",{status:"BLOCKED"})}>Bloquear</button>}{bulkEnabled&&<button className="danger ghostDanger" onClick={()=>ask({title:"Excluir "+kind.toLowerCase()+" permanentemente?",message:"Você está prestes a remover "+x.name+" da Porto Prime.",detail:kind==="Motoboy"?"O cadastro, acesso e dados vinculados serão removidos. Motoboys com entrega ativa não podem ser excluídos.":"Clientes com histórico de pedidos são preservados para manter a integridade operacional e financeira.",confirm:"Sim, excluir "+kind.toLowerCase(),action:()=>act("/admin/users/"+x.id,"DELETE")})}>Excluir</button>}</div></td></tr>})}</tbody></table></div>)}
 </Panel>{detail&&kind==="Motoboy"&&<CourierAdminProfile user={detail} app={detailApp} close={()=>setProfileId(null)} act={act} requestRequirement={requestRequirement}/>}</>
}

function CourierAdminProfile({user,app,close,act,requestRequirement}:{user:Row,app:Row,close:()=>void,act:any,requestRequirement:(app:Row,name:string)=>void}){
 const [finance,setFinance]=useState<Row|null>(null),[financeError,setFinanceError]=useState("");
 const [editing,setEditing]=useState(false),[draft,setDraft]=useState<Row>({}),[saving,setSaving]=useState(false),[editError,setEditError]=useState("");
 useEffect(()=>{let active=true;const refresh=async()=>{try{const r=await api("/admin/couriers/"+app.id+"/finance");if(active){setFinance(r);setFinanceError("")}}catch(e:any){if(active)setFinanceError(e.message)}};refresh();const timer=setInterval(refresh,10000);return()=>{active=false;clearInterval(timer)}},[app.id]);
 const onboarding=app.onboardingData||user.courierProfile?.onboardingData||{};
 const labels:Record<string,string>={name:"Nome",birthDate:"Data de nascimento",cpf:"CPF",cpfSituation:"Situação do CPF",document:"Documento",cnh:"Número da CNH",cnhCategory:"Categoria CNH",cnhExpiry:"Validade da CNH",vehicleType:"Tipo de veículo",vehicleBrand:"Marca",vehicleModel:"Modelo",vehicleYear:"Ano",vehiclePlate:"Placa",pixKey:"Chave PIX",pixKeyType:"Tipo de chave PIX",cep:"CEP",postalCode:"CEP",street:"Rua",number:"Número",complement:"Complemento",neighborhood:"Bairro",city:"Cidade",state:"Estado",phone:"Telefone",email:"E-mail",hasMotorcycle:"Possui moto"};
 const format=(v:any):string=>v===null||v===undefined||v===""?"Não informado":typeof v==="boolean"?(v?"Sim":"Não"):Array.isArray(v)?v.map(format).join(" · "):typeof v==="object"?Object.entries(v).map(([k,x])=>(labels[k]||k)+": "+format(x)).join("; "):String(v);
 const data={...onboarding,...Object.fromEntries(Object.entries(app).filter(([k,v])=>["document","cnh","cnhCategory","vehicleBrand","vehicleModel","vehicleYear","vehiclePlate","pixKey","pixKeyType"].includes(k)&&v!==null&&v!==undefined&&v!=="")),name:user.name,email:user.email,phone:user.phone};
 const editable=['name','email','phone','birthDate','cnh','cnhCategory','cnhExpiry','vehicleType','vehicleBrand','vehicleModel','vehicleYear','vehiclePlate','postalCode','cep','street','number','complement','neighborhood','city','state','pixKey','pixKeyType'];
 const beginEdit=()=>{setDraft(Object.fromEntries(editable.map(k=>[k,String(data[k]??"")])));setEditError("");setEditing(true)};
 const save=async(e:React.FormEvent)=>{e.preventDefault();setSaving(true);setEditError("");const changes=Object.fromEntries(editable.filter(k=>draft[k]!==String(data[k]??"")).map(k=>[k,draft[k]]));try{if(Object.keys(changes).length){await api("/admin/couriers/"+app.id+"/profile","","PATCH",changes);await act("/admin/couriers/"+app.id+"/finance","GET")}setEditing(false)}catch(e:any){setEditError(e.message)}finally{setSaving(false)}};
 const sections=[{title:"Dados pessoais e contato",keys:["name","cpf","document","birthDate","cpfSituation","email","phone"]},{title:"Habilitação e veículo",keys:["hasMotorcycle","cnh","cnhCategory","cnhExpiry","vehicleType","vehicleBrand","vehicleModel","vehicleYear","vehiclePlate"]},{title:"Endereço",keys:["cep","postalCode","street","number","complement","neighborhood","city","state"]},{title:"Recebimentos via PIX",keys:["pixKeyType","pixKey"]}];
 const used=new Set(sections.flatMap(g=>g.keys));
 const extras=Object.keys(data).filter(k=>!used.has(k)&&k!=="profilePhoto"&&!/(password|senha|token|secret)/i.test(k));
 const field=(k:string)=><div key={k}><span>{labels[k]||k.replace(/([A-Z])/g," $1")}</span><b>{format(data[k])}</b></div>;
 return <div className="modalBackdrop profileBackdrop" onMouseDown={close}><section className="profileModal courierFullProfile" role="dialog" aria-modal="true" aria-labelledby="courier-profile-title" onMouseDown={e=>e.stopPropagation()}><div className="profileModalHero"><button autoFocus className="profileClose" aria-label="Fechar perfil" onClick={close}><X size={18}/></button><div className="profileModalAvatar">{onboarding.profilePhoto?<img src={onboarding.profilePhoto} alt={"Foto de "+user.name}/>:((user.name||"?").slice(0,1).toUpperCase())}</div><div><small>PERFIL COMPLETO · MOTOBOY</small><h2 id="courier-profile-title">{user.name}</h2><p>Cadastrado em {dt(user.createdAt)}</p></div><Badge v={app.approvalStatus||user.status}/></div><div className="profileSummary"><div><span>Acesso à plataforma</span><Badge v={user.status}/></div><div><span>Disponibilidade</span><b>{app.isOnline?"Online":"Offline"}</b></div><div><span>Última atualização</span><b>{dt(app.updatedAt)}</b></div></div><section className="profileSection courierFinancial"><div className="profileSectionTitle"><span><Wallet size={16}/></span><div><b>Ganhos e saques</b><small>Valores registrados na carteira deste motoboy</small></div></div>{financeError&&<p className="error">{financeError}</p>}{!finance&&!financeError&&<div className="financeSkeleton" aria-label="Carregando resumo financeiro"/>}{finance&&<><div className="courierFinanceGrid"><div><span>Ganhos com entregas</span><b>{brl(finance.earningsTotal)}</b><small>{finance.deliveries} entregas concluídas</small></div><div><span>Saldo disponível</span><b>{brl(finance.availableBalance)}</b><small>{brl(finance.pendingWithdrawalTotal)} em saques pendentes</small></div><div><span>Saques pagos</span><b>{brl(finance.paidWithdrawalTotal)}</b><small>{finance.paidWithdrawalCount} saques realizados</small></div></div><h4>Histórico de solicitações</h4><div className="courierWithdrawalList">{finance.withdrawals.map((w:Row)=><article key={w.id}><div><b>{brl(w.amount)}</b><small>{dt(w.requestedAt)}</small><span>{w.pixKeyType} · {w.pixKey}</span>{w.processedAt&&<small>Processado em {dt(w.processedAt)}</small>}</div><Badge v={w.status}/></article>)}{!finance.withdrawals.length&&<p className="courierProfileEmpty">Nenhum saque solicitado.</p>}</div></>}</section><section className="profileSection courierProfileAccess"><div className="profileSectionTitle"><span><UserCheck size={16}/></span><div><b>Gerenciar acesso</b><small>Status atual: {statusLabel[user.status]||user.status}</small></div></div><div className="actions">{user.status!=="ACTIVE"&&<button onClick={()=>act("/admin/users/"+user.id+"/status","PATCH",{status:"ACTIVE"})}><Check size={16}/> Ativar acesso</button>}{user.status==="ACTIVE"&&<button className="warn" onClick={()=>act("/admin/users/"+user.id+"/status","PATCH",{status:"SUSPENDED"})}><CircleAlert size={16}/> Suspender acesso</button>}{user.status!=="BLOCKED"&&<button className="danger" onClick={()=>act("/admin/users/"+user.id+"/status","PATCH",{status:"BLOCKED"})}><CircleAlert size={16}/> Bloquear acesso</button>}</div></section><section className="profileSection courierEditSection"><div className="courierEditHeading"><div><b>Dados da conta</b><p>Atualize as informações solicitadas pelo motoboy.</p></div>{!editing&&<button className="secondary" onClick={beginEdit}><SettingsIcon size={16}/> Editar dados</button>}</div>{editing&&<form className="courierEditForm" onSubmit={save}><p>CPF e permissões de acesso permanecem nos fluxos próprios de verificação.</p>{editable.map(k=><label key={k}>{labels[k]||k}{k==="pixKeyType"?<select value={draft[k]} disabled={saving} onChange={e=>setDraft({...draft,[k]:e.target.value})}><option value="">Selecione</option>{['CPF','CNPJ','EMAIL','PHONE','RANDOM'].map(v=><option key={v} value={v}>{v}</option>)}</select>:<input value={draft[k]} disabled={saving} type={k==="email"?"email":"text"} maxLength={250} onChange={e=>setDraft({...draft,[k]:e.target.value})}/>}</label>)}{editError&&<div className="error" role="alert">{editError}</div>}<div className="courierEditActions"><button type="button" className="secondary" disabled={saving} onClick={()=>setEditing(false)}>Cancelar</button><button disabled={saving}>{saving?"Salvando…":"Salvar alterações"}</button></div></form>}</section>{sections.map((g,i)=><section className="profileSection" key={g.title}><div className="profileSectionTitle"><span>{String(i+1).padStart(2,"0")}</span><div><b>{g.title}</b><small>Informações do cadastro e perfil atual</small></div></div><div className="profileDataGrid full">{g.keys.filter(k=>k in data||["pixKey","pixKeyType"].includes(k)).map(field)}</div></section>)}{extras.length>0&&<section className="profileSection"><div className="profileSectionTitle"><span>05</span><div><b>Outras informações do formulário</b><small>Campos adicionais enviados no cadastro</small></div></div><div className="profileDataGrid full">{extras.map(field)}</div></section>}<section className="profileSection"><div className="profileSectionTitle"><span><ClipboardList size={16}/></span><div><b>Pendências e respostas</b><small>Histórico completo da candidatura</small></div></div>{app.id&&<button className="secondary" onClick={()=>requestRequirement(app,user.name)}>Solicitar informação ou documento</button>}<div className="profileHistory">{(app.requirements||[]).map((r:Row)=><div key={r.id}><div><b>{r.title}</b><Badge v={r.status}/></div><p>{r.description}</p><small>{dt(r.requestedAt)}</small>{r.response&&<strong>Resposta: {r.response}</strong>}{r.status==="ANSWERED"&&<button onClick={()=>act("/admin/requirements/"+r.id+"/resolve","PATCH")}><Check size={15}/> Marcar como resolvida</button>}</div>)}{!app.requirements?.length&&<p className="courierProfileEmpty">Nenhuma pendência registrada.</p>}</div></section><div className="profileModalFooter"><span>PORTO PRIME · CADASTRO E OPERAÇÃO</span><button onClick={close}>Fechar perfil</button></div></section></div>;
}

function Orders({rows,act,ask,token}:{rows:Row[],act:any,ask:any,token:string}){
 const [audit,setAudit]=useState<{order:Row;events:Row[]}|null>(null);
 const [auditBusy,setAuditBusy]=useState(false);
 const [selected,setSelected]=useState<Set<string>>(new Set());
 useEffect(()=>{const valid=new Set(rows.map(x=>x.id));setSelected(prev=>new Set([...prev].filter(id=>valid.has(id))))},[rows]);
 const [orderQuery,setOrderQuery]=useState("");
 const [visibleLimit,setVisibleLimit]=useState(20);
 const normalizedQuery=orderQuery.trim().replace(/^#/,"").toLowerCase();
 const filteredRows=rows.filter(o=>String(o.id).toLowerCase().includes(normalizedQuery));
 const visibleRows=filteredRows.slice(0,visibleLimit);
 const allVisible=visibleRows.length>0&&visibleRows.every(x=>selected.has(x.id));
 const toggle=(id:string)=>setSelected(prev=>{const next=new Set(prev);next.has(id)?next.delete(id):next.add(id);return next});
 const toggleAll=()=>setSelected(prev=>{const next=new Set(prev);visibleRows.forEach(x=>allVisible?next.delete(x.id):next.add(x.id));return next});
 const selectedRows=rows.filter(x=>selected.has(x.id));
 const bulkDelete=()=>ask({
  title:"Excluir "+selectedRows.length+" pedido(s)?",
  message:"Os pedidos selecionados serão removidos definitivamente do histórico operacional.",
  detail:"Pedidos já coletados ou em rota serão preservados automaticamente por segurança. Os demais selecionados serão excluídos.",
  confirm:"Excluir "+selectedRows.length+" pedido(s)",
  action:async()=>{const result=await act("/admin/orders/bulk-delete","POST",{ids:selectedRows.map(x=>x.id)});if(result)setSelected(new Set())}
 });
 const openAudit=async(o:Row)=>{setAuditBusy(true);try{const events=await api("/admin/orders/"+o.id+"/audit",token);setAudit({order:o,events})}catch(e:any){alert(e.message)}finally{setAuditBusy(false)}};
 const preStatuses=["PENDING","CONFIRMED","PREPARING","READY_FOR_PICKUP","CANCELED"];
 return <><Panel title="Gestão de pedidos">
  <div className="orderSearchToolbar">
   <label className="orderNumberSearch"><Search size={19}/><input aria-label="Buscar pelo número do pedido" placeholder="Buscar número do pedido…" value={orderQuery} onChange={e=>{setOrderQuery(e.target.value);setVisibleLimit(20)}}/>{orderQuery&&<button type="button" aria-label="Limpar busca de pedidos" onClick={()=>{setOrderQuery("");setVisibleLimit(20)}}><X size={16}/></button>}</label>
   <span role="status">{filteredRows.length} {filteredRows.length===1?"pedido":"pedidos"}{normalizedQuery?" encontrados":" na operação"}</span>
  </div>
  <div className={"bulkBar orderBulkBar "+(selected.size?"active":"")}>
   <div className="bulkSelectAll">
    <label className="checkControl"><input aria-label="Selecionar pedidos exibidos" type="checkbox" checked={allVisible} onChange={toggleAll}/><span/></label>
    <div><b>{selected.size?selected.size+" pedido(s) selecionado(s)":"Selecionar pedidos exibidos"}</b><small>{selected.size?"Revise os selecionados antes de excluir":"Selecione um ou vários pedidos para ações em massa"}</small></div>
   </div>
   <div className="bulkActions">{selected.size>0&&<button className="secondary" onClick={()=>setSelected(new Set())}>Limpar seleção</button>}<button className="bulkDeleteBtn" disabled={!selected.size} onClick={bulkDelete}><Trash2 size={16}/> Excluir selecionados</button></div>
  </div>
  {!filteredRows.length?<Empty text={normalizedQuery?"Nenhum pedido com esse número. Confira o número ou limpe a busca.":"Nenhum pedido encontrado."}/>:<div className="orderCards">{visibleRows.map(o=>{const isSelected=selected.has(o.id);return <article className={"orderCard "+(isSelected?"selectedOrder":"")} key={o.id}><div className="orderHead"><div className="orderIdentity"><label className="checkControl orderCheck"><input aria-label={"Selecionar pedido "+o.id} type="checkbox" checked={isSelected} onChange={()=>toggle(o.id)}/><span/></label><div><small>PEDIDO</small><b>#{o.id.slice(-8).toUpperCase()}</b></div></div><Badge v={o.status}/><strong>{brl(o.total)}</strong></div><details className="orderExpansion"><summary><span>{o.customer?.name||"Cliente"}<small>{dt(o.createdAt)} · {o.items?.length||0} itens</small></span><span className="orderExpandLabel">Ver pedido<ChevronDown size={17}/></span></summary><div className="orderExpandedBody"><div className="orderGrid"><div><span>Cliente</span><b>{o.customer?.name}</b><small>{o.customer?.phone}</small></div><div><span>Pagamento</span><Badge v={o.paymentStatus}/><small>{o.paymentMethod||"—"}</small></div><div><span>Entrega</span><b>{o.address?.street}, {o.address?.number}</b><small>{o.address?.neighborhood}</small></div><div><span>Motoboy</span><b>{o.courier?.user?.name||(["SEARCHING_COURIER"].includes(o.status)?"Busca automática ativa":"Não atribuído")}</b><small>{o.routeDistanceKm?Number(o.routeDistanceKm).toFixed(1)+" km por rota":""}</small></div></div><details className="orderDetails"><summary><span><PackageSearch size={18}/> Detalhes do pedido <small>{o.items?.length||0} itens</small></span><ChevronDown size={18}/></summary><div className="items">{o.items?.map((i:Row)=><span key={i.id}>{i.quantity}× {i.productName} <b>{brl(i.total)}</b></span>)}</div></details>{o.status==="SEARCHING_COURIER"&&<div className="dispatchActive"><b>● Despacho automático em andamento</b><span>O sistema está oferecendo esta entrega aos motoboys online e disponíveis. Recusas e expirações passam automaticamente ao próximo candidato.</span></div>}<div className="actions">{preStatuses.includes(o.status)&&<select value={o.status} onChange={e=>act("/admin/orders/"+o.id+"/status","PATCH",{status:e.target.value})}>{preStatuses.map(s=><option key={s} value={s}>{statusLabel[s]||s}</option>)}</select>}{o.paymentStatus==="PAID"&&["CONFIRMED","PREPARING","READY_FOR_PICKUP"].includes(o.status)&&<button onClick={()=>act("/admin/orders/"+o.id+"/release")}><Check size={16}/> Liberar pedido</button>}<button className="secondary" disabled={auditBusy} onClick={()=>openAudit(o)}><History size={16}/> Histórico da entrega</button><button className="danger ghostDanger" onClick={()=>ask({title:"Excluir permanentemente este pedido?",message:"O pedido #"+o.id.slice(-8).toUpperCase()+" será removido definitivamente da operação.",detail:"Cliente: "+(o.customer?.name||"—")+" · Valor: "+brl(o.total)+". Pedidos em entrega são preservados por segurança.",confirm:"Sim, excluir pedido",action:()=>act("/admin/orders/"+o.id,"DELETE")})}><Trash2 size={16}/> Excluir pedido</button></div></div></details></article>})}</div>}
 {visibleRows.length<filteredRows.length&&<div className="orderMore"><span>Exibindo {visibleRows.length} de {filteredRows.length} pedidos</span><button className="secondary" onClick={()=>setVisibleLimit(n=>n+20)}>Mostrar mais 20 pedidos</button></div>}
 </Panel>{audit&&<div className="modalBackdrop profileBackdrop" onMouseDown={()=>setAudit(null)}><section className="profileModal auditModal" onMouseDown={e=>e.stopPropagation()}><div className="profileModalHero"><button className="profileClose" aria-label="Fechar" onClick={()=>setAudit(null)}><X size={18}/></button><div className="profileModalAvatar">#</div><div><small>HISTÓRICO DA ENTREGA</small><h2>Pedido #{audit.order.id.slice(-8).toUpperCase()}</h2><p>Acompanhe cada etapa, da liberação à conclusão.</p></div><Badge v={audit.order.status}/></div><div className="profileSection"><div className="profileHistory">{audit.events.length?audit.events.map((e:Row)=><div key={e.id}><div><b>{dispatchEventLabel(e.type)}</b><span>{dt(e.createdAt)}</span></div>{e.courierId&&<p>Motoboy: {e.courierId}</p>}{e.offerId&&<p>Oferta: {e.offerId}</p>}{e.payload&&<strong>{JSON.stringify(e.payload)}</strong>}</div>):<div className="none">Nenhum evento registrado para este pedido.</div>}</div></div><div className="profileModalFooter"><span>PORTO PRIME · ACOMPANHAMENTO</span><button onClick={()=>setAudit(null)}>Fechar</button></div></section></div>}</>;
}

const dispatchEventLabel=(v:string)=>({ADMIN_RELEASED:"Admin liberou o pedido",SEARCH_STARTED:"Busca por motoboy iniciada",OFFER_CREATED:"Oferta enviada",OFFER_DECLINED:"Oferta recusada",OFFER_EXPIRED:"Oferta expirada",OFFER_CANCELED:"Oferta cancelada",OFFER_ACCEPTED:"Motoboy aceitou",COURIER_PICKED_UP:"Pedido coletado",OUT_FOR_DELIVERY:"Saiu para entrega",DELIVERED:"Entrega concluída",WALLET_CREDITED:"Carteira creditada"} as Record<string,string>)[v]||v;

function Payments({rows}:{rows:Row[]}){const paid=rows.filter(x=>x.paymentStatus==="PAID").reduce((s,x)=>s+Number(x.total||0),0);return <><section className="metrics payMetrics"><Card icon={Banknote} label="Volume pago" value={brl(paid)} note="Transações aprovadas"/><Card icon={Check} label="Pagos" value={rows.filter(x=>x.paymentStatus==="PAID").length} note="Pedidos"/><Card icon={CircleAlert} label="Pendentes" value={rows.filter(x=>x.paymentStatus==="PENDING").length} note="Aguardando confirmação"/><Card icon={CircleAlert} label="Falhas" value={rows.filter(x=>x.paymentStatus==="FAILED").length} note="Transações"/></section><Panel title="Histórico financeiro"><div className="tableWrap"><table><thead><tr><th>Pedido</th><th>Cliente</th><th>Método</th><th>Status</th><th>Valor</th><th>Data</th></tr></thead><tbody>{rows.map(o=><tr key={o.id}><td>#{o.id.slice(-7).toUpperCase()}</td><td>{o.customer?.name}</td><td>{o.paymentMethod||"—"}</td><td><Badge v={o.paymentStatus}/></td><td><b>{brl(o.total)}</b></td><td>{dt(o.createdAt)}</td></tr>)}</tbody></table></div></Panel></>}
function Catalog({categories,act}:{categories:Row[],act:any}){
 const [productOpen,setProductOpen]=useState(false),[categoryOpen,setCategoryOpen]=useState(false);
 const [form,setForm]=useState<Row>({categoryId:"",name:"",price:"",stock:0,description:""});
 const [cat,setCat]=useState("");
 const submit=(e:React.FormEvent)=>{e.preventDefault();act("/admin/products","POST",{...form,price:Number(form.price),stock:Number(form.stock)});setProductOpen(false)};
 const submitCategory=(e:React.FormEvent)=>{e.preventDefault();act("/admin/categories","POST",{name:cat});setCat("");setCategoryOpen(false)};
 return <><div className="toolbar"><div><b>{categories.reduce((s,c)=>s+c.products.length,0)} produtos</b><span>{categories.length} categorias cadastradas · catálogo sincronizado com o app</span></div><div className="actions"><button className="secondary" onClick={()=>setCategoryOpen(!categoryOpen)}>+ Nova categoria</button><button onClick={()=>{setForm({categoryId:categories[0]?.id||"",name:"",price:"",stock:0,description:""});setProductOpen(!productOpen)}}>+ Novo produto</button></div></div>
 {categoryOpen&&<form className="productForm categoryForm" onSubmit={submitCategory}><label>Nome da nova categoria<input autoFocus value={cat} onChange={e=>setCat(e.target.value)} placeholder="Ex.: Destilados" required/></label><button>Criar categoria</button></form>}
 {productOpen&&<form className="productForm" onSubmit={submit}><label>Categoria<select value={form.categoryId} onChange={e=>setForm({...form,categoryId:e.target.value})} required><option value="" disabled>Selecione</option>{categories.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label><label>Produto<input value={form.name} onChange={e=>setForm({...form,name:e.target.value})} required/></label><label>Preço<input type="number" step=".01" min="0" value={form.price} onChange={e=>setForm({...form,price:e.target.value})} required/></label><label>Estoque<input type="number" min="0" value={form.stock} onChange={e=>setForm({...form,stock:e.target.value})} required/></label><button>Salvar e publicar</button></form>}
 <div className="catalog">{categories.map(c=><section key={c.id}><div className="catTitle"><div><b>{c.name}</b><span>{c.products.length} produtos</span></div><Badge v={c.active?"ACTIVE":"BLOCKED"}/></div><div className="productGrid">{c.products.map((p:Row)=><article key={p.id} className={!p.active||p.stock<=0?"unavailableProduct":""}><div className="productPic">{p.imageUrl?<img src={p.imageUrl} alt=""/>:"P"}</div><div className="grow"><b>{p.name}</b><span>{brl(p.price)}</span><small>{p.stock>0?p.stock+" em estoque":"SEM ESTOQUE"}</small>{!p.active&&<em className="unavailableTag">INDISPONÍVEL NO APP</em>}</div><input className="stock" title="Estoque" type="number" min="0" defaultValue={p.stock} onBlur={e=>Number(e.target.value)!==p.stock&&act("/admin/products/"+p.id,"PATCH",{stock:Number(e.target.value)})}/><button className={p.active?"warn":""} onClick={()=>act("/admin/products/"+p.id,"PATCH",{active:!p.active})}>{p.active?"Marcar indisponível":"Disponibilizar"}</button></article>)}</div></section>)}</div></>
}
function Withdrawals({rows,act}:{rows:Row[],act:any}){
 const pending=rows.filter(x=>x.status==="PENDING"||x.status==="PROCESSING").reduce((s,x)=>s+Number(x.amount||0),0);
 const paid=rows.filter(x=>x.status==="PAID").reduce((s,x)=>s+Number(x.amount||0),0);
 return <><section className="metrics payMetrics"><Card icon={Wallet} label="Aguardando" value={brl(pending)} note="Pendente / processamento"/><Card icon={Banknote} label="Já pagos" value={brl(paid)} note="Confirmações administrativas"/><Card icon={ClipboardList} label="Solicitações" value={rows.length} note="Histórico total"/><Card icon={CircleAlert} label="Pendentes" value={rows.filter(x=>x.status==="PENDING").length} note="Precisam de análise"/></section><Panel title="Solicitações de saque — análise e pagamento manual">{!rows.length?<Empty text="Nenhum saque solicitado."/>:<div className="tableWrap"><table><thead><tr><th>Motoboy</th><th>Valor</th><th>PIX</th><th>Status</th><th>Solicitado</th><th>Ações</th></tr></thead><tbody>{rows.map(w=><tr key={w.id}><td><b>{w.courier?.user?.name||"Motoboy"}</b><small>{w.courier?.user?.email||""}</small></td><td><b>{brl(w.amount)}</b></td><td>{w.pixKeyType}<small>{w.pixKey}</small></td><td><Badge v={w.status}/></td><td>{dt(w.requestedAt)}</td><td><div className="actions">{w.status==="PENDING"&&<button onClick={()=>act("/admin/withdrawals/"+w.id+"/status","PATCH",{status:"PROCESSING"})}>Em processamento</button>}{w.status==="PROCESSING"&&<button onClick={()=>act("/admin/withdrawals/"+w.id+"/status","PATCH",{status:"PAID"})}>Confirmar PIX realizado</button>}{["PENDING","PROCESSING"].includes(w.status)&&<button className="danger" onClick={()=>act("/admin/withdrawals/"+w.id+"/status","PATCH",{status:"REJECTED"})}>Rejeitar</button>}</div>{w.status==="PROCESSING"&&<small>Marque como pago somente após confirmar o repasse no provedor/PIX externo.</small>}</td></tr>)}</tbody></table></div>}</Panel></>;
}
function Settings({me,dash,pricing,act}:{me:Row,dash:Row,pricing:Row,act:any}){
 const [form,setForm]=useState<Row>({});
 useEffect(()=>{setForm(pricing||{})},[pricing]);
 const field=(key:string,label:string,step="0.01")=><label>{label}<input type="number" step={step} value={form[key]??""} onChange={e=>setForm({...form,[key]:e.target.value})}/></label>;
 const save=(e:React.FormEvent)=>{e.preventDefault();act("/delivery/pricing-config","PATCH",{distributorName:form.distributorName,distributorAddress:form.distributorAddress,distributorLatitude:form.distributorLatitude===""?null:Number(form.distributorLatitude),distributorLongitude:form.distributorLongitude===""?null:Number(form.distributorLongitude),baseFee:Number(form.baseFee),includedKm:Number(form.includedKm),pricePerAdditionalKm:Number(form.pricePerAdditionalKm),maxDistanceKm:Number(form.maxDistanceKm),minDeliveryFee:Number(form.minDeliveryFee),maxDeliveryFee:Number(form.maxDeliveryFee),offerTimeoutSeconds:Number(form.offerTimeoutSeconds),heartbeatTimeoutSeconds:Number(form.heartbeatTimeoutSeconds),platformCommissionPercent:Number(form.platformCommissionPercent||0)})};
 return <div className="settings"><section className="settingsHero"><div className="avatar big">{me.name?.[0]}</div><div><small>CONTA ADMINISTRATIVA</small><h2>{me.name}</h2><p>{me.email}</p></div><Badge v={me.status}/></section><div className="grid"><Panel title="Ambiente"><dl className="settingsList"><dt>Arquitetura</dt><dd>Admin Web → NestJS → PostgreSQL + Socket.IO</dd><dt>Sessão</dt><dd>Multi-dispositivo · access token curto · refresh rotativo</dd><dt>Despacho</dt><dd>Automático e auditável</dd></dl></Panel><Panel title="Resumo da plataforma"><dl className="settingsList"><dt>Usuários</dt><dd>{dash.users||0}</dd><dt>Produtos ativos</dt><dd>{dash.products||0}</dd><dt>Pedidos registrados</dt><dd>{dash.orders||0}</dd></dl></Panel></div><section className="panel pricingPanel"><div className="panelHead"><div><h3>Entrega e despacho</h3><span>Valores operacionais configuráveis sem alterar código</span></div></div><form className="pricingForm" onSubmit={save}><label>Nome da base<input value={form.distributorName??""} onChange={e=>setForm({...form,distributorName:e.target.value})}/></label><label>Endereço da base<input value={form.distributorAddress??""} onChange={e=>setForm({...form,distributorAddress:e.target.value})} placeholder="Região central de Porto Seguro/BA"/></label>{field("distributorLatitude","Latitude da base","0.0000001")}{field("distributorLongitude","Longitude da base","0.0000001")}{field("baseFee","Taxa mínima/base")}{field("includedKm","KM incluídos")}{field("pricePerAdditionalKm","Valor por KM adicional")}{field("maxDistanceKm","Distância máxima (km)")}{field("minDeliveryFee","Valor mínimo da entrega")}{field("maxDeliveryFee","Valor máximo da entrega")}{field("offerTimeoutSeconds","Tempo da oferta (segundos)","1")}{field("heartbeatTimeoutSeconds","Timeout heartbeat (segundos)","1")}{field("platformCommissionPercent","Comissão da plataforma (%)")}<div className="pricingNote"><b>Rota viária</b><span>Com latitude/longitude da base configuradas, o checkout usa geocodificação + rota viária. Comissão em 0% significa repasse de 100% da taxa ao motoboy.</span></div><button>Salvar configuração operacional</button></form></section></div>;
}
function Empty({text}:{text:string}){return <div className="none" role="status"><div className="emptyIcon"><PackageSearch size={26} aria-hidden="true"/></div><strong>Tudo organizado por aqui</strong><p>{text}</p></div>}
